import {swatchKind,sourceGradient,countLabelAppearance} from './swatch.mjs';
import {RAMP_LABELS,RAMPS,colourMeta,sectionsOf,packColumns,combineLikeColours} from './wall.mjs';
import {latestCatalog} from './data.mjs';
import {filterPaints,swatchBackground} from './core.mjs';
const $=id=>document.getElementById(id),PAGE_SIZE=48;
let data,filtered=[],state={q:'',brand:'',range:'',type:'',status:'',sort:'color',view:'wall',group:'type',family:'',size:36,combine:true,page:1,paint:''},paintById=new Map(),sourceById=new Map(),ready=false;
function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
function link(text,url){const a=el('a','',text);try{const u=new URL(url,location.origin);if(['https:','http:'].includes(u.protocol))a.href=u.href;}catch{}return a;}
function readState(){const p=new URLSearchParams(location.search);for(const key of ['q','brand','range','type','status','paint','family'])state[key]=p.get(key)||'';state.sort=['brand','name','hue','color','code'].includes(p.get('sort'))?p.get('sort'):'color';if(state.sort==='hue')state.sort='color';if(state.sort==='brand'){state.group='range';state.sort='color';}else state.group=['type','brand','range','none'].includes(p.get('group'))?p.get('group'):'type';state.view=['grid','list','wall'].includes(p.get('view'))?p.get('view'):'wall';state.size=Math.max(20,Math.min(96,Number(p.get('size'))||36));state.page=Math.max(1,parseInt(p.get('page'),10)||1);state.combine=p.get('combine')!=='false';}
function writeState(){const p=new URLSearchParams();const defaults={sort:'color',view:'wall',group:'type',size:36,combine:true,page:1};for(const [key,value]of Object.entries(state))if(value!==''&&value!==null&&value!==undefined&&value!==defaults[key])p.set(key,value);history.replaceState(null,'',location.pathname+(p.size?'?'+p:''));}
function options(id,values,label){const node=$(id),previous=state[id];node.replaceChildren(new Option(label,''));for(const v of [...new Set(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b)))node.add(new Option(v,id==='type'?v:v));node.value=previous;if(node.value!==previous){state[id]='';node.value='';}}
function ranges(){options('range',data.paints.filter(p=>!state.brand||p.brand===state.brand).map(p=>p.range),'All ranges');}
function indexes(){paintById=new Map(data.paints.map(p=>[p.id,p]));sourceById=new Map(data.sources.colour_sources.map(s=>[s.id,s]));}
function metadata(){const brands=new Set(data.paints.map(p=>p.brand));$('total').textContent=`${data.paints.length.toLocaleString()} paints · ${brands.size} brands`;const coloured=data.paints.filter(p=>p.colour).length;$('coverage').replaceChildren(document.createTextNode(`${coloured.toLocaleString()} with a published colour · `),link(`${data.paints.length-coloured} without`,'/catalogue/?family=unknown'));$('snapshot').replaceChildren(link(`Catalog revision ${data.revision.slice(0,7)}`,`https://github.com/paintcommons/catalog/commit/${data.revision}`));}
function buildSwatch(p,className){const n=el('span',className);const bg=swatchBackground(p);n.dataset.finish=swatchKind(p);if(bg)n.style.background=bg;else{n.classList.add('no-swatch');n.append(el('span','missing-label','No published swatch'));}n.setAttribute('aria-hidden','true');return n;}
function paintCard(p){const card=el('button','paint-card');card.type='button';card.setAttribute('aria-label',`${p.name}, ${p.brand}, ${p.range||'no range'}${p.code?', '+p.code:''}. View record`);card.append(buildSwatch(p,'card-swatch'));const body=el('span','card-body');body.append(el('span','card-brand',p.brand),el('span','card-name',p.name),el('span','card-range',p.range||'Range not recorded'));const bottom=el('span','card-bottom');bottom.append(el('span','paint-type',p.type+(p.status==='discontinued'?' · discontinued':'')),el('span','paint-code',p.code||'Code not recorded'));body.append(bottom);card.append(body);card.addEventListener('click',()=>openPaint(p.id));return card;}
function wallTile(tile,named,familyLabel){const p=tile.paint;const button=el('button','wall-tile');button.type='button';const label=`${p.name} · ${p.brand} · ${p.range||'Other'}${p.code?' · '+p.code:''}`;button.title=label+(tile.paints.length>1?` + ${tile.paints.length-1} similar paints`:'');button.setAttribute('aria-label',tile.paints.length>1?`${tile.paints.length} similar colours. ${label}. Choose a paint`:label+'. View record');if(named)button.append(el('span','ramp-cap',familyLabel||''));const chip=buildSwatch(p,'wall-chip');if(tile.paints.length>1){const badge=el('span','similar-count','+'+(tile.paints.length-1));const appearance=countLabelAppearance(p);badge.dataset.tone=appearance.tone;badge.style.color=appearance.color;badge.style.background=appearance.background;chip.append(badge);}button.append(chip);if(named){button.append(el('span','tile-name',p.name),el('span','tile-brand',p.brand));}button.addEventListener('click',()=>tile.paints.length>1?openCluster(tile.paints):openPaint(p.id));return button;}
function paintPalette(){const palette=$('family-palette');palette.replaceChildren();for(const [key,label]of RAMP_LABELS){const n=el('button','family-swatch');n.type='button';n.title=label;n.setAttribute('aria-label',label);n.setAttribute('aria-pressed',String(state.family===key));const ramp=RAMPS.find(r=>r.key===key);const samples=ramp?data.paints.filter(p=>colourMeta(p).family===key&&p.colour).sort((a,b)=>colourMeta(a).lightness-colourMeta(b).lightness):[];if(samples.length){const picks=[samples[0],samples[Math.floor(samples.length/2)],samples.at(-1)];n.style.background=`linear-gradient(to bottom,${picks.map(p=>p.colour.hex).join(',')})`;}else n.classList.add('no-swatch');n.addEventListener('click',()=>{state.family=state.family===key?'':key;$('family').value=state.family;state.page=1;render();});palette.append(n);}}
function render(){const wall=state.view==='wall';filtered=filterPaints(data.paints,wall?{...state,sort:'color'}:state);const pages=Math.max(1,Math.ceil(filtered.length/PAGE_SIZE));state.page=Math.min(state.page,pages);const start=(state.page-1)*PAGE_SIZE,shown=wall?filtered:filtered.slice(start,start+PAGE_SIZE);const sections=sectionsOf(shown,state.group);const clustered=wall?sections.map(sec=>({...sec,tiles:combineLikeColours(sec.paints,state.combine)})):[];const swatches=clustered.reduce((n,sec)=>n+sec.tiles.length,0);const active=['brand','range','type','status','family'].filter(k=>state[k]).length;$('filter-toggle').textContent='Filters'+(active?' · '+active:'');$('result-count').textContent=wall?`${filtered.length.toLocaleString()} paints · ${swatches.toLocaleString()} swatches · ${sections.length} ${state.group==='range'?(sections.length===1?'range':'ranges'):state.group==='brand'?(sections.length===1?'brand':'brands'):(sections.length===1?'group':'groups')}`:filtered.length?`${start+1}–${start+shown.length} of ${filtered.length.toLocaleString()} paints`:'0 paints';const container=$('paint-grid');container.className=wall?'colour-wall':'catalogue-sections';container.replaceChildren();const gap=state.size>=56?6:3,cols=Math.max(3,Math.floor((container.clientWidth+gap)/(state.size+gap))),named=state.size>=56,labels=new Map(RAMP_LABELS);for(const sec of sections){const section=el('section','paint-section');const heading=el('h2','section-title',sec.label);const tiles=wall?clustered.find(s=>s.key===sec.key).tiles:[];heading.append(el('span','',wall?`${sec.paints.length} paints · ${tiles.length} swatches`:String(sec.paints.length)));section.append(heading);if(wall){const {bands}=packColumns(tiles,cols);for(const band of bands){const grid=el('div','wall-grid'+(named?' named':''));grid.style.gridTemplateColumns=`repeat(${cols},minmax(0,1fr))`;grid.style.gap=gap+'px';band.forEach((column,c)=>column.paints.forEach((p,r)=>{const tile=wallTile(p,named,r===0?labels.get(column.family):'');tile.style.gridColumn=c+1;tile.style.gridRow=r+1;grid.append(tile);}));section.append(grid);}}else{const grid=el('div','paint-grid'+(state.view==='list'?' list-view':''));for(const p of sec.paints)grid.append(paintCard(p));section.append(grid);}container.append(section);}container.setAttribute('aria-busy','false');$('empty').hidden=filtered.length>0;document.querySelector('.pagination').hidden=wall||!filtered.length;$('previous').disabled=state.page<=1;$('next').disabled=state.page>=pages;$('page-label').textContent=`Page ${state.page} of ${pages}`;for(const view of ['wall','grid','list'])$(view+'-view').setAttribute('aria-pressed',String(state.view===view));$('wall-controls').hidden=!wall;$('combine').checked=state.combine;$('sort').disabled=wall;$('sort').title=wall?'The wall follows colour families from dark to light':'';if(wall)$('sort').value='color';$('swatch-size').value=state.size;$('smaller').disabled=state.size<=20;$('larger').disabled=state.size>=96;$('wall-family-label').textContent=state.family?' / '+labels.get(state.family):'';for(const n of $('family-palette').children)n.setAttribute('aria-pressed',String(n.title===labels.get(state.family)));writeState();}
function openCluster(paints){state.paint='';writeState();const content=$('detail-content');content.replaceChildren();const inner=el('div','detail-inner');inner.append(el('p','eyebrow','Similar swatches'));const heading=el('h2','',`${paints.length} paints, one colour group`);heading.id='detail-name';inner.append(heading,el('p','','Grouped by approximate colour across brands, within the same colour family and paint group. This is visual similarity, not a declared paint equivalence.'));for(const p of paints){const button=el('button','cluster-record');button.type='button';button.append(buildSwatch(p,'cluster-swatch'));const text=el('span');text.append(el('strong','',p.name),el('small','',`${p.brand} · ${p.range||'Other'}${p.code?' · '+p.code:''}`));button.append(text,el('span','','→'));button.addEventListener('click',()=>{openPaint(p.id);$('paint-dialog').scrollTop=0;});inner.append(button);}content.append(inner);if(!$('paint-dialog').open)$('paint-dialog').showModal();}

function row(dl,label,value){const r=el('div');r.append(el('dt','',label));const dd=el('dd');if(value instanceof Node)dd.append(value);else dd.textContent=value; r.append(dd);dl.append(r);}
function openPaint(id){const p=paintById.get(id);if(!p)return;state.paint=id;writeState();const content=$('detail-content');content.replaceChildren();const swatch=buildSwatch(p,'detail-swatch');swatch.removeAttribute('aria-hidden');if(p.colour)swatch.append(el('span','',p.colour.hex+' · approximate'));content.append(swatch);const inner=el('div','detail-inner');inner.append(el('div','eyebrow',p.brand));const heading=el('h2','',p.name);heading.id='detail-name';inner.append(heading,el('p','',p.range||'Range not recorded'));const dl=el('dl');row(dl,'Product code',p.code||'Not recorded');row(dl,'Paint type',p.type);row(dl,'Status',p.status==='current'?'Current':'Discontinued');row(dl,'Stable ID',p.id);inner.append(dl);inner.append(el('h3','','Swatch & evidence'));const evidence=el('div','evidence');const source=sourceById.get(p.colour?.source);if(source){evidence.append(link(source.name,source.url),el('p','',source.method));if(source.id==='miniature-paints')evidence.append(el('p','','Source credit: miniature-paints by b-kelly (MIT).'));evidence.append(el('p','','Digital approximation. Not a measured match; lighting, finish, surface, and application affect the result.'));const kind=swatchKind(p);if(kind==='speed')evidence.append(el('p','','The three bands are illustrative shadow, base colour, and highlight shades generated from the base swatch, as in Stipplewise. They are not three measured colours.'));if(kind==='metal')evidence.append(el('p','','The metallic sheen is an illustrative gradient generated from the base swatch, as in Stipplewise. It does not measure reflectivity or colour shift.'));if(sourceGradient(p)){evidence.append(el('p','','Source gradient stops (separate from the illustrative finish):'));const strip=el('div','source-gradient');strip.style.background=sourceGradient(p);strip.setAttribute('role','img');strip.setAttribute('aria-label','Published source gradient stops');evidence.append(strip);}}else evidence.append(el('p','','No swatch with a published source is available for this record.'));inner.append(evidence);inner.append(el('h3','','Barcodes'));if(!p.barcodes.length)inner.append(el('p','','No barcode recorded.'));for(const b of p.barcodes){const n=el('div','barcode-row');n.append(el('code','',b.ean),el('span','',b.source==='scan'?'Confirmed by scan':b.source==='published'?'Published source':'Calculated · not confirmed by scan'));if(b.source_url)n.append(link('Barcode source ↗',b.source_url));inner.append(n);}const pairs=data.equivalents.filter(e=>e.paint_a===id||e.paint_b===id);if(pairs.length){inner.append(el('h3','','Declared equivalents'));for(const pair of pairs){const other=paintById.get(pair.paint_a===id?pair.paint_b:pair.paint_a);if(!other)continue;const button=el('button','equivalent',`${other.name} — ${other.brand} →`);button.type='button';button.addEventListener('click',()=>{openPaint(other.id);$('paint-dialog').scrollTop=0;});inner.append(button,el('p','source-caption',`Declared ${pair.kind}: ${pair.source}`));}inner.append(el('p','source-caption','A published equivalence is a source’s claim, not a guarantee of identical behaviour.'));}const actions=el('div','detail-actions');actions.append(link('View source record ↗',`https://github.com/paintcommons/catalog/blob/${data.revision}/${p.file}`),link('Suggest a correction ↗',`https://github.com/paintcommons/catalog/edit/main/${p.file}`));const share=el('button','share','Copy record link');share.type='button';share.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);share.textContent='Link copied';}catch{share.textContent='Copy the URL from your address bar';}});actions.append(share);inner.append(actions);content.append(inner);if(!$('paint-dialog').open)$('paint-dialog').showModal();}
function reset(){for(const k of ['q','brand','range','type','status','family'])state[k]='';state.page=1;$('search').value='';for(const id of ['brand','type','status','family'])$(id).value='';ranges();render();}
function wire(){if(ready)return;ready=true;let timer;$('filter-toggle').addEventListener('click',()=>{const open=$('filter-toggle').getAttribute('aria-expanded')!=='true';$('filter-toggle').setAttribute('aria-expanded',String(open));$('filter-panel').classList.toggle('mobile-open',open);});$('search').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{state.q=$('search').value;state.page=1;render();},120);});for(const id of ['brand','range','type','status','sort','family','group'])$(id).addEventListener('change',()=>{state[id]=$(id).value;state.page=1;if(id==='brand')ranges();render();});for(const id of ['clear','empty-reset'])$(id).addEventListener('click',reset);for(const view of ['wall','grid','list'])$(view+'-view').addEventListener('click',()=>{state.view=view;render();});for(const [id,delta]of [['previous',-1],['next',1]])$(id).addEventListener('click',()=>{state.page+=delta;render();document.querySelector('.toolbar').scrollIntoView({block:'start'});});$('combine').addEventListener('change',()=>{state.combine=$('combine').checked;render();});$('swatch-size').addEventListener('input',()=>{state.size=Number($('swatch-size').value);render();});for(const [id,delta]of [['smaller',-12],['larger',12]])$(id).addEventListener('click',()=>{state.size=Math.max(20,Math.min(96,state.size+delta));render();});let width=0,tick;new ResizeObserver(entries=>{const next=Math.floor(entries[0].contentRect.width);if(next!==width){width=next;cancelAnimationFrame(tick);tick=requestAnimationFrame(()=>{if(data&&state.view==='wall')render();});}}).observe($('paint-grid'));$('close-dialog').addEventListener('click',()=>$('paint-dialog').close());$('paint-dialog').addEventListener('close',()=>{state.paint='';writeState();});$('paint-dialog').addEventListener('click',e=>{if(e.target===$('paint-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('paint-dialog').open){e.preventDefault();$('search').focus();}});addEventListener('popstate',()=>{readState();apply();});}
function apply(){indexes();metadata();options('brand',data.paints.map(p=>p.brand),'All brands');options('type',data.paints.map(p=>p.type),'All types');ranges();const family=$('family');family.replaceChildren(new Option('All colour families',''));for(const [key,label]of RAMP_LABELS)family.add(new Option(label,key));paintPalette();for(const id of ['status','sort','group','family'])$(id).value=state[id];$('search').value=state.q;render();if(state.paint){if(paintById.has(state.paint))openPaint(state.paint);else{state.paint='';writeState();}}}
async function load(){try{$('error').hidden=true;const response=await fetch('/data/catalogue.json');if(!response.ok)throw Error('Snapshot unavailable');data=await response.json();readState();wire();apply();refresh();}catch{$('result-count').textContent='Catalogue unavailable';$('paint-grid').setAttribute('aria-busy','false');$('error').hidden=false;document.querySelector('.pagination').hidden=true;}}
$('retry').addEventListener('click',load);
async function refresh(){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),18000);try{const latest=await latestCatalog(data.revision,{signal:controller.signal});if(latest){data=latest;apply();}}catch{/* Keep the bundled, revision-labelled snapshot if GitHub is unavailable. */}finally{clearTimeout(timeout);}}
load();
